"""Declarative base, constraint naming convention and shared column mixins.

Conventions (docs/backend/DATA_MODEL.md §2, BACKEND_ARCHITECTURE.md §9):

* Constraint and index names are deterministic: ``pk_``, ``fk_``, ``uq_``, ``ck_``, ``ix_`` + table
  and column(s). Multi-column constraints and checks are named explicitly where they are declared,
  so Alembic output and database error messages are readable and stable.
* Every id is a UUID (``uuid.uuid4()``, standard library) generated by the application; there is no
  database-side default, so an id can never be silently invented by a raw INSERT. The column type
  is PostgreSQL's native ``uuid``.
* Every timestamp is ``timestamptz`` (UTC). ``created_at`` is database-generated (``now()``);
  ``updated_at`` is database-generated on insert and refreshed by the ORM on update. ``now()`` is
  the *transaction* start time, so all rows written in one transaction share a timestamp.
"""

import uuid
from datetime import datetime

from sqlalchemy import DateTime, MetaData, Uuid, func
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column

NAMING_CONVENTION = {
    "ix": "ix_%(column_0_label)s",
    "uq": "uq_%(table_name)s_%(column_0_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}


class Base(DeclarativeBase):
    metadata = MetaData(naming_convention=NAMING_CONVENTION)


class UUIDPrimaryKeyMixin:
    id: Mapped[uuid.UUID] = mapped_column(
        Uuid, primary_key=True, default=uuid.uuid4, sort_order=-10
    )


class TimestampMixin:
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=func.now(), sort_order=10
    )
    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        nullable=False,
        server_default=func.now(),
        onupdate=func.now(),
        sort_order=11,
    )
